import{_ as l,l as i,o as e,c as d,v as o,p as n,x as t,d as c,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"子类型与协变逆变","description":"","frontmatter":{"title":"子类型与协变逆变","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/subtyping-variance.md","filePath":"cs/subtyping-variance.md","lastUpdated":1789023840000}'),h={name:"cs/subtyping-variance.md"};function _(m,a,T,u,f,A){const r=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="子类型与协变逆变" tabindex="-1">子类型与协变逆变 <a class="header-anchor" href="#子类型与协变逆变" aria-label="Permalink to &quot;子类型与协变逆变&quot;">​</a></h1><div class="epigraph"><p>$S\\lt :T$ 表示 $S$ 的值可用在要 $T$ 的地方。函数在参数上逆变、在结果上协变；容器的可变性决定能不能协变。</p><footer>—— 据 Cardelli, Type Systems；Pierce TAPL 第 15–16 章；Liskov, Data Abstraction and Hierarchy 整理</footer></div><p>上一课<a href="/cs/let-polymorphism">值限制</a>处理量化与可变。缺口是另一轴：<strong>子类型</strong>——名义或结构的宽化，以及数组/函数的变型（variance）。主干<a href="/cs/overload-coerce">overload 与强制</a>有强制转换；本课钉 \\(\\lt :\\) 规则，不把 Java 数组协变的历史事故当推荐设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 合一对称。面向对象与记录：<code>Dog &lt;: Animal</code> 则 <code>Dog</code> 的值可传给要 <code>Animal</code> 的参数（宽度子类型可再谈字段）。函数：若用 \\(S\\to U\\) 去填 \\(T\\to V\\) 的坑，需要 \\(T\\lt :S\\)（参数更挑剔）且 \\(U\\lt :V\\)（结果更宽大）。缺口是<strong>变型</strong>，不是再写 W。</p><p>可变数组：写与读同时存在，只该不变（invariant）。Java 历史上让数组协变，运行时 <code>ArrayStoreException</code>——类型在静态上不健全。</p><h3 id="不是继承图的别名" tabindex="-1"><code>&lt;:</code> 不是继承图的别名 <a class="header-anchor" href="#不是继承图的别名" aria-label="Permalink to &quot;`&lt;:` 不是继承图的别名&quot;">​</a></h3><p>继承可诱导名义子类型；结构子类型看字段。强制（<code>int</code> 到 <code>float</code>）有时不是子类型而是另一次转换。不要混。</p><p><span class="marginnote">Pierce TAPL 子类型章。Cardelli 综述。Liskov 替换原则是规格层，本课用它对照「能不能代换」与「函数变型」。Appel 在面向对象章点过方法类型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给出记录的宽度/深度规则（点名即可）。函数变型按上面陈述。泛型参数标 <code>+</code>/<code>-</code>/<code>0</code>（Scala/Kotlin 习惯），检查定义体是否遵守。检查算法：加入子类型约束后不再是对称合一，要用边界或双向检查（后课渐进也会用）。</p>',11)),(e(),n(p,null,{default:t(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20USE%5B%22%E8%A6%81%20T%22%5D%20--%3E%20SUB%5B%22%E6%9C%89%20S%20%E4%B8%94%20S%20%EF%BC%9C%3A%20T%22%5D%0A%20%20FUN%5B%22S%E2%86%92U%20%EF%BC%9C%3A%20T%E2%86%92V%22%5D%20--%3E%20CONTRA%5B%22T%20%EF%BC%9C%3A%20S%22%5D%0A%20%20FUN%20--%3E%20CO%5B%22U%20%EF%BC%9C%3A%20V%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 HM：可先实例化再问子类型，或把量化与子类型合成（有界量化 \\(\\forall\\alpha\\lt :T\\)），本课点名，不写 System F\\({}_{\\lt :}\\) 全文。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可变引用：<code>ref S &lt;: ref T</code> 只当 \\(S=T\\)。只读视图可以协变；只写可以逆变。这与值限制同一精神：可变破坏宽化。</p><p>不要为了「方便把 Dog[] 当 Animal[]」牺牲健全性；API 用不变泛型或只读切片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多重继承的 C3，不算结构子类型的判定复杂度细节。后课默认：函数参数逆变、结果协变；可变不变。下一课泛型实现：单态化对擦除——变型在擦除语言里靠桥接方法。</p><p>也不把 Python 的鸭子类型当静态 \\(\\lt :\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>子类型是安全代换；函数参数逆变、结果协变。</li><li>可变容器应不变。</li><li>与 HM 量化正交，可合成有界量化。</li><li>出处：Pierce TAPL；Cardelli；对照 Liskov。</li></ul>',9))])}const P=l(h,[["render",_]]);export{C as __pageData,P as default};
